class Solution {
    public int maxArea(int[] height) {
        int left = 0;
        int right = height.length - 1;
        int maxArea = 0;

        while (left < right) {
            int width = right - left;
            int limitingHeight = Math.min(height[left], height[right]);
            int area = width * limitingHeight;
            maxArea = Math.max(maxArea, area);

            if (height[left] <= height[right]) {
                left++;
            } else {
                right--;
            }
        }

        return maxArea;
    }
}

class Solution {
    public int maxArea(int[] height) {
        int left = 0;
        int right = height.length - 1;
        int maxArea = 0;

        while (left < right) {
            int limitingHeight = Math.min(height[left], height[right]);
            maxArea = Math.max(maxArea, limitingHeight * (right - left));

            if (height[left] <= height[right]) {
                int currentLeft = height[left];
                while (left < right && height[left] <= currentLeft) {
                    left++;
                }
            } else {
                int currentRight = height[right];
                while (left < right && height[right] <= currentRight) {
                    right--;
                }
            }
        }

        return maxArea;
    }
}

class Solution {
    public int maxArea(int[] height) {
        Integer[] order = new Integer[height.length];
        for (int i = 0; i < height.length; i++) {
            order[i] = i;
        }
        java.util.Arrays.sort(order, (a, b) -> Integer.compare(height[b], height[a]));

        int minIndex = height.length;
        int maxIndex = -1;
        int maxArea = 0;
        int cursor = 0;

        while (cursor < order.length) {
            int currentHeight = height[order[cursor]];
            while (cursor < order.length && height[order[cursor]] == currentHeight) {
                int index = order[cursor];
                minIndex = Math.min(minIndex, index);
                maxIndex = Math.max(maxIndex, index);
                cursor++;
            }
            if (maxIndex > minIndex) {
                maxArea = Math.max(maxArea, currentHeight * (maxIndex - minIndex));
            }
        }

        return maxArea;
    }
}

class Solution {
    public int maxArea(int[] height) {
        int maxArea = 0;

        for (int i = 0; i < height.length; i++) {
            for (int j = i + 1; j < height.length; j++) {
                int width = j - i;
                int limitingHeight = Math.min(height[i], height[j]);
                maxArea = Math.max(maxArea, width * limitingHeight);
            }
        }

        return maxArea;
    }
}
